diff --git a/repro/no-useless-assignment-try-catch.js b/repro/no-useless-assignment-try-catch.js
new file mode 100644
index 0000000..3327ca5
--- /dev/null
+++ b/repro/no-useless-assignment-try-catch.js
@@ -0,0 +1,112 @@
+"use strict";
+
+/*
+ * Reproduction for no-useless-assignment false positive in try/catch (eslint#19245).
+ * Run from repo root: node repro/no-useless-assignment-try-catch.js
+ * Exits 1 if the bug reproduces (any case that should be clean gets reported).
+ */
+
+const { Linter } = require("../lib/api");
+
+const linter = new Linter({ configType: "flat" });
+
+const cases = [
+    {
+        name: "report: return in try, value read in catch",
+        code: `async function fn() {
+  let intermediaryValue;
+  try {
+    intermediaryValue = 42;
+    unsafeFn();
+    return { error: undefined };
+  } catch {
+    return { intermediaryValue };
+  }
+}`
+    },
+    {
+        name: "break in try, value read in catch",
+        code: `function fn() {
+  let v;
+  while (cond) {
+    try {
+      v = 42;
+      unsafeFn();
+      break;
+    } catch {
+      use(v);
+    }
+  }
+}`
+    },
+    {
+        name: "throw in try, value read in catch",
+        code: `function fn() {
+  let v;
+  try {
+    v = 42;
+    unsafeFn();
+    throw new Error();
+  } catch {
+    use(v);
+  }
+}`
+    },
+    {
+        name: "control: no return in try (expected clean, already passes)",
+        code: `function fn() {
+  let v;
+  try {
+    v = 42;
+    unsafeFn();
+  } catch {
+    use(v);
+  }
+}`
+    }
+];
+
+let failed = false;
+
+for (const { name, code } of cases) {
+    const messages = linter.verify(code, {
+        languageOptions: { ecmaVersion: "latest", sourceType: "module" },
+        rules: { "no-useless-assignment": "error" }
+    });
+    const status = messages.length ? "FALSE POSITIVE" : "ok";
+
+    if (messages.length) {
+        failed = true;
+    }
+    console.log(`[${status}] ${name}`);
+    for (const m of messages) {
+        console.log(`    ${m.line}:${m.column} ${m.ruleId}: ${m.message}`);
+    }
+}
+
+// Show the code path: the segment containing `intermediaryValue = 42` has no path into the catch clause.
+const segInfo = [];
+
+linter.verify(cases[0].code, {
+    languageOptions: { ecmaVersion: "latest" },
+    plugins: {
+        dbg: {
+            rules: {
+                segs: {
+                    create: () => ({
+                        onCodePathSegmentStart(seg, node) {
+                            segInfo.push({ seg, node: `${node.type}@${node.loc.start.line}` });
+                        }
+                    })
+                }
+            }
+        }
+    },
+    rules: { "dbg/segs": "error" }
+});
+console.log("\nCode path segments for the reported case (segment: started at -> next segments):");
+for (const { seg, node } of segInfo) {
+    console.log(`    ${seg.id} (${node}) -> [${seg.nextSegments.map(s => s.id).join(", ")}]${seg.reachable ? "" : " (unreachable)"}`);
+}
+
+process.exitCode = failed ? 1 : 0;
